<?php require __DIR__.'/bootstrap.php'; page('Danh mục sản phẩm', function () { ?><div class="grid"><?php foreach (products() as $p): ?><article class="card"><img src="<?=htmlspecialchars($p['image_url'])?>" alt=""><h2><?=htmlspecialchars($p['name'])?></h2><p><?=htmlspecialchars($p['description'])?></p><p class="price"><?=number_format((float)$p['price'],0,',','.')?> đ</p><a class="button" href="/detail.php?id=<?=(int)$p['id']?>">Xem chi tiết</a></article><?php endforeach; ?></div><?php });
